//@ProcessingGroup("kPI")
@Component("kPI-projector")
public class KPIProjector extends KPIEntityProjector {
		
	// core constructor
	public KPIProjector(ProjectorRegistry registry,
									KPIRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateKPIEvent
     */
    @EventHandler( payloadType=CreateKPIEvent.class )
    public void handle( CreateKPIEvent event) {
	    LOGGER.info("handling CreateKPIEvent - " + event );
	    KPI entity = new KPI();
            entity.setKPIId( event.getKPIId() );
            entity.setTargetValue( event.getTargetValue() );
            entity.setMetricType( event.getMetricType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllKPI( entity );
    }

    /*
     * @param	event UpdateKPIEvent
     */
    @EventHandler( payloadType=UpdateKPIEvent.class )
    public void handle( UpdateKPIEvent event) {
    	LOGGER.info("handling UpdateKPIEvent - " + event );
    	
	    KPI entity = new KPI();
            entity.setKPIId( event.getKPIId() );
            entity.setTargetValue( event.getTargetValue() );
            entity.setCampaign( event.getCampaign() );
            entity.setMetricType( event.getMetricType() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindKPI( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllKPI( entity );        
    }
    
    /*
     * @param	event DeleteKPIEvent
     */
    @EventHandler( payloadType=DeleteKPIEvent.class )
    public void handle( DeleteKPIEvent event) {
    	LOGGER.info("handling DeleteKPIEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	KPI entity = delete( event.getKPIId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllKPI( entity );

    }    

    /*
     * @param	event AssignCampaignToKPIEvent
     */
    @EventHandler( payloadType=AssignCampaignToKPIEvent.class)
    public void handle( AssignCampaignToKPIEvent event) {
	    LOGGER.info("handling AssignCampaignToKPIEvent - " + event );

	    // ------------------------------------------
	    // delegate to assignTo
	    // ------------------------------------------
	    KPI entity = assignCampaign( event.getKPIId(), event.getAssignment() );

	    // ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindKPI( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllKPI( entity );
    }
    

	/*
	 * @param	event UnAssignCampaignFromKPIEvent
	 */
	@EventHandler( payloadType=UnAssignCampaignFromKPIEvent.class)
	public void handle( UnAssignCampaignFromKPIEvent event) {
	    LOGGER.info("handling UnAssignCampaignFromKPIEvent - " + event );

	    // ------------------------------------------
	    // delegate to unAssignFrom
	    // ------------------------------------------
	    KPI entity = unAssignCampaign( event.getKPIId() );

		// ------------------------------------------
		// emit to subscribers that find one
		// ------------------------------------------    	
	    emitFindKPI( entity );
	
		// ------------------------------------------
		// emit to subscribers that find all
		// ------------------------------------------    	
	    emitFindAllKPI( entity );
	}




    /**
     * Method to retrieve the KPI via an KPIPrimaryKey.
     * @param 	id Long
     * @return 	KPI
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public KPI handle( FindKPIQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getKPIId() );
    }
    
    /**
     * Method to retrieve a collection of all KPIs
     *
     * @param	query	FindAllKPIQuery 
     * @return 	List<KPI> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<KPI> handle( FindAllKPIQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindKPI,
 * but only if the id matches
 *
 * @param		entity	KPI
 */
	protected void emitFindKPI( KPI entity ) {
		LOGGER.info("handling emitFindKPI" );
		
	    queryUpdateEmitter.emit(FindKPIQuery.class,
	                            query -> query.getFilter().getKPIId().equals(entity.getKPIId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllKPI
	 * 
	 * @param		entity	KPI
	 */
	protected void emitFindAllKPI( KPI entity ) {
		LOGGER.info("handling emitFindAllKPI" );
		
	    queryUpdateEmitter.emit(FindAllKPIQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(KPIProjector.class.getName());

}
